def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1

    for i in range(n - 1, -1, -1):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            topmost_carpet = i + 1
            break

    return topmost_carpet

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]
    dp[0][0] = [grid[0][0], 0]

    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            max_val = 0
            if i > 0:
                max_val = max(max_val, dp[i-1][j][0], dp[i-1][j][1])
            if j > 0:
                max_val = max(max_val, dp[i][j-1][0], dp[i][j-1][1])
            dp[i][j] = [grid[i][j] + max_val, -float('inf')]

    max_values = []
    for i in range(N):
        for j in range(N):
            if i == N-1 and j == N-1:
                max_values.append(dp[i][j][0])
                max_values.append(dp[i][j][1])

    return max(max_values)

