def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n + 1):
        coeff = coeffs[n - i]
        if coeff != 0:
            if i == 0:
                if coeff == -1:
                    terms.append('-1')
                elif coeff == 1:
                    terms.append('1')
                else:
                    terms.append(str(coeff))
            elif i == 1:
                if coeff == -1:
                    terms.append('-x')
                elif coeff == 1:
                    terms.append('x')
                else:
                    terms.append(f'{coeff}x')
            else:
                if coeff == -1:
                    terms.append(f'-x^{i}')
                elif coeff == 1:
                    terms.append(f'x^{i}')
                else:
                    terms.append(f'{coeff}x^{i}')
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original) or len(message) != len(encoded):
        return "Failed"

    mapping = {}
    for en_char, or_char in zip(encoded, original):
        if en_char in mapping and mapping[en_char] != or_char:
            return "Failed"
        mapping[en_char] = or_char

    decoded_message = []
    for en_char in message:
        if en_char in mapping:
            decoded_message.append(mapping[en_char])
        else:
            return "Failed"

    return ''.join(decoded_message)

