            remaining_money -= 100
        else:
            return -i

    return int(savings)

def minimum_students_to_leave(heights: List[int]) -> int:
    n = len(heights)
    if n <= 2:
        return 0

    max_height = max(heights)
    max_index = heights.index(max_height)

    left_increasing = [0] * n
    for i in range(n):
        if i == 0:
            left_increasing[i] = 1
        elif heights[i] > heights[i - 1]:
            left_increasing[i] = left_increasing[i - 1] + 1
        else:
            left_increasing[i] = 1

    right_decreasing = [0] * n
    for i in range(n - 1, -1, -1):
        if i == n - 1:
            right_decreasing[i] = 1
        elif heights[i] > heights[i + 1]:
            right_decreasing[i] = right_decreasing[i + 1] + 1
        else:
            right_decreasing[i] = 1

    min_students_to_leave = n
    for i in range(n):
        if left_increasing[i] + right_decreasing[i] >= n:
            continue
        min_students_to_leave = min(min_students_to_leave, n - (left_increasing[i] + right_decreasing[i] - 1))

    return min_students_to_leave
